// ===== Paramètres =====
const START_DATE = '2026-10-01';    // CFS créés ou modifiés à partir de cette date (fuseau ci-dessous)
const TZ = 'Europe/Paris';
const EXCLUDE_NAME = /^test\b/i;     // écarte les specs de test

const specs = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j)) specs.push(...j);
  else if (Array.isArray(j.data)) specs.push(...j.data);
  else specs.push(j);
}
const localDate = iso => {
  if (!iso) return null;
  const d = new Date(iso);
  return isNaN(d) ? null : d.toLocaleDateString('sv-SE', { timeZone: TZ });   // YYYY-MM-DD
};
const isCFS = s => (s['@type'] || '').toLowerCase().includes('customerfacing');

// CFS datés de START_DATE ou après (comparaison de chaînes YYYY-MM-DD)
const candidates = specs.filter(s => {
  const d = localDate(s.lastUpdate);
  return isCFS(s) && d !== null && d >= START_DATE && !EXCLUDE_NAME.test(s.name || '');
});

// Dédoublonnage par nom : la version la plus récente
const byName = new Map();
for (const s of candidates) {
  const prev = byName.get(s.name);
  if (!prev || new Date(s.lastUpdate) > new Date(prev.lastUpdate)) byName.set(s.name, s);
}
const selected = [...byName.values()];
if (selected.length === 0) {
  throw new Error(`Aucun CFS daté du ${START_DATE} ou après, parmi ${specs.length} spécifications lues.`);
}
// La liste OpenSlice ne contient pas les caractéristiques : on ne transmet que l'id
return selected.map(s => ({ json: { id: s.id, name: s.name, lastUpdate: s.lastUpdate } }));

// Chaque item est une spec complète renvoyée par GET /serviceSpecification/{id}
// Caractéristiques déclarées comme métadonnées dans le Default Data Loader (catalogue aligné GST)
const KNOWN = new Set(["Availability", "Isolation level: Isolation", "Isolation level: Logical Isolation", "Area of Service", "Area of Service: Region specification", "Downlink throughput per network slice: Guaranteed downlink throughput quota", "Uplink throughput per network slice: Guaranteed uplink throughput quota", "Downlink maximum throughput per UE: Maximum downlink throughput per UE value", "Uplink maximum throughput per UE: Maximum Uplink Throughput per UE value", "Isolation level: Physical Isolation", "UE density", "Maximum number of UEs", "NB-IoT Support", "Delay tolerance", "Slice quality of service: 3GPP 5QI", "Slice quality of service: Packet Delay Budget", "Slice quality of service: Packet Error Rate", "Deterministic communication: Availability", "Deterministic communication: Periodicity", "Latency from (last) UPF to Application Server", "Supported device velocity", "V2X-PC5 Network Scheduled Mode", "Positioning support: Accuracy", "Session and Service Continuity support", "Positioning support: Availability", "Mission critical support", "Mission critical support: Mission-critical capability support", "Mission critical support: Mission-critical service support", "Group communication support", "Data network access: Data access per data network", "Synchronicity: Availability", "Synchronicity: Accuracy", "User management openness", "Network Slice Specific Authentication and Authorization (NSSAA) Required", "Data network access: Tunnelling mechanism", "Edge", "Price"]);

const TIERS = ['Basic', 'Premium', 'Gold'];
const tierOf = name => TIERS.find(t => new RegExp(`\\b${t}$`, 'i').test(name || '')) || 'N/A';
const valOf = c => {
  const vals = c.serviceSpecCharacteristicValue || [];
  const v = vals.find(x => x.isDefault) || vals[0];
  return v && v.value ? { value: v.value.value, alias: v.value.alias, unit: v.unitOfMeasure } : null;
};
const SKIP = new Set(['SSPEC_GRAPH_NOTATION']);

const out = [];
for (const it of $input.all()) {
  const s = it.json;
  const meta = {};          // nom de caractéristique -> "valeur unité (alias)"
  for (const c of (s.serviceSpecCharacteristic || [])) {
    if (SKIP.has(c.name)) continue;
    const v = valOf(c);
    if (!v) continue;
    const unit = v.unit && !['NA', 'N/A'].includes(v.unit) ? ` ${v.unit}` : '';
    const alias = v.alias ? ` (${v.alias})` : '';
    meta[c.name] = `${v.value}${unit}${alias}`;
  }
  // Conserver chaque CFS reçu, même sans Availability ou Isolation level: Isolation.
  const unmapped = Object.keys(meta).filter(n => !KNOWN.has(n));
  const rels = (s.serviceSpecRelationship || []).map(r => `- ${r.name} [${r.role || 'n/a'}]`);
  const tier = tierOf(s.name);
  // TMF633 : isBundle = true si la spec est un bundle (composée d'autres CFS)
  const isBundle = s.isBundle === true || String(s.isBundle).toLowerCase() === 'true';
  const text = [
    `Service: ${s.name}`,
    `spec_id: ${s.id}`,
    `Type: CFS (orderable customer service)`,
    `Tier: ${tier}`,
    `isBundle: ${isBundle}`,
    `Description: ${s.description || ''}`,
    `Characteristics (GSMA GST NG.116):`,
    ...Object.entries(meta).map(([n, v]) => `- ${n}: ${v}`),
    ...(rels.length ? ['Realized by (RFS):', ...rels] : []),
  ].join('\n');

  out.push({ json: {
    text, spec_id: s.id, name: s.name, kind: 'CFS', tier, isBundle, lastUpdate: s.lastUpdate, meta,
    // n'apparaît dans Qdrant que si une caractéristique inconnue doit être ajoutée au Data Loader
    unmapped_characteristics: unmapped.length ? unmapped.join(', ') : undefined,
  }});
}
return out;
